from rdkit import Chem
rxn='[N][C][=C][C][=C][N][=C][Ring1][=Branch1].[O][=C][Branch1][C][O][C][C][C][C][=N][O][C][=Ring1][Branch1][C][=C][C][=C][Branch1][C][Cl][C][=C][Ring1][#Branch1]>>[O][=C][Branch2][Ring1][Branch1][C][C][C][C][=N][O][C][=Ring1][Branch1][C][=C][C][=C][Branch1][C][Cl][C][=C][Ring1][#Branch1][N][C][=C][C][=C][N][=C][Ring1][=Branch1]'
parts=rxn.split('>>')
for label,s in [('reactants',parts[0]),('product',parts[1])]:
    print(label)
    for i,x in enumerate(s.split('.')):
        m=Chem.MolFromSmiles(x)
        print(i, 'parsed=',m is not None, 'atoms=', m.GetNumAtoms() if m else None)
        if m: print(Chem.MolToSmiles(m))
print('reaction parsed', Chem.rdChemReactions.ChemicalReaction if False else '')
